-- PARALLEL Interview Studio — initial schema
--
-- This file is the authoritative definition of everything the app needs in a
-- Supabase project: tables, constraints, indexes, row-level security policies,
-- column grants and the SECURITY DEFINER functions the client calls by name.
-- It was generated by reading the live database catalogs (pg_policies,
-- pg_constraint, pg_indexes, information_schema.column_privileges) so it
-- matches what the app is actually running against, not an aspiration.
--
-- Apply it to a fresh project with either:
--   npx supabase migration up --db-url "$DATABASE_URL"
--   -- or paste into the Supabase dashboard SQL Editor and run
--
-- Everything is namespaced `pl_` so the schema can share a project with other
-- apps. The whole file is idempotent (IF NOT EXISTS / OR REPLACE / DROP POLICY
-- IF EXISTS) so re-running it is safe.
--
-- SECURITY MODEL IN ONE PARAGRAPH
-- Every table has RLS enabled and no policy grants blanket access. Membership
-- is decided by pl_session_participants, which has a SELECT policy and nothing
-- else — no client can INSERT into it. The only way in is pl_join_session(), a
-- SECURITY DEFINER function that derives the role from the room key: the
-- creator gets `interviewer`, a confirmed-email address on the invite list gets
-- `interviewer`, everybody else gets the single `candidate` seat. A client
-- never sends a role. pl_is_participant()/pl_is_interviewer() then read that
-- table on behalf of every other policy. See SECURITY.md for the reasoning and
-- the verification queries.

-- ---------------------------------------------------------------------------
-- Extensions
-- ---------------------------------------------------------------------------
-- gen_random_uuid() is built in on Postgres 13+, which every Supabase project
-- is. pgcrypto is listed for older self-hosted installs.
create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

-- Mirror of auth.users, populated by the pl_on_auth_user_created trigger below.
-- pl_join_session reads display_name from here when seating an interviewer.
create table if not exists public.pl_profiles (
  id           uuid primary key references auth.users(id) on delete cascade,
  display_name text,
  email        text,
  is_anonymous boolean     not null default false,
  created_at   timestamptz not null default now()
);

-- Question bank. owner_id null = builtin, readable by every signed-in user;
-- otherwise the row is private to its owner.
--
-- hidden_tests is deliberately NOT in the SELECT grant for `authenticated`
-- (see the GRANT block below). RLS gates rows, not columns, so the column-level
-- revoke is the only thing keeping a candidate — or any signed-in user probing
-- the bank — from reading the hidden tests of a builtin problem. The server
-- reads it with the service role and merges it into the session at create time.
create table if not exists public.pl_problems (
  id            uuid primary key default gen_random_uuid(),
  owner_id      uuid references auth.users(id) on delete cascade,
  number        integer,
  title         text        not null,
  difficulty    text        not null default 'easy' check (difficulty in ('easy','medium','hard')),
  description   text        not null default '',
  follow_up     text,
  tags          text[]      not null default '{}',
  hints         jsonb       not null default '[]',
  starter_code  jsonb       not null default '{}',
  visible_tests jsonb       not null default '[]',
  hidden_tests  jsonb       not null default '[]',
  created_at    timestamptz not null default now()
);

-- One interview room. room_key is the sole credential for the candidate seat,
-- so it is unique and generated server-side; see src/lib/keys.ts for the
-- canonical PXR-XXXXXX shape and scripts/keys.test.mjs for its properties.
create table if not exists public.pl_sessions (
  id                   uuid primary key default gen_random_uuid(),
  created_by           uuid        not null references auth.users(id) on delete cascade,
  room_key             text        not null unique,
  status               text        not null default 'scheduled' check (status in ('scheduled','live','completed')),
  candidate_name       text        not null default 'Candidate',
  candidate_role_label text        not null default '',
  problem_id           uuid references public.pl_problems(id) on delete set null,
  problem_number       integer,
  problem_title        text        not null default '',
  difficulty           text        not null default 'easy' check (difficulty in ('easy','medium','hard')),
  description          text        not null default '',
  follow_up            text,
  tags                 text[]      not null default '{}',
  hints                jsonb       not null default '[]',
  language             text        not null default 'python' check (language in ('python','javascript','java','cpp','go')),
  code                 jsonb       not null default '{}',
  starter_code         jsonb       not null default '{}',
  started_at           timestamptz,
  ended_at             timestamptz,
  created_at           timestamptz not null default now()
);

-- Seating. Written ONLY by pl_join_session (SECURITY DEFINER) — there is no
-- INSERT/UPDATE/DELETE policy, which is what makes role and display_name
-- trustworthy identity for the rest of the app.
create table if not exists public.pl_session_participants (
  id           uuid primary key default gen_random_uuid(),
  session_id   uuid        not null references public.pl_sessions(id) on delete cascade,
  user_id      uuid        not null references auth.users(id) on delete cascade,
  role         text        not null check (role in ('interviewer','candidate')),
  display_name text        not null default '',
  color        text        not null default '#3ddc97',
  joined_at    timestamptz not null default now(),
  unique (session_id, user_id)
);

-- Co-interviewer invites. pl_join_session promotes a joiner to interviewer only
-- if their CONFIRMED email is on this list, so an unverified signup cannot
-- claim someone else's address to escalate.
create table if not exists public.pl_session_invites (
  id         uuid primary key default gen_random_uuid(),
  session_id uuid        not null references public.pl_sessions(id) on delete cascade,
  email      text        not null,
  role       text        not null default 'interviewer' check (role = 'interviewer'),
  invited_by uuid        not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (session_id, email)
);

create table if not exists public.pl_test_cases (
  id         uuid primary key default gen_random_uuid(),
  session_id uuid        not null references public.pl_sessions(id) on delete cascade,
  position   integer     not null default 0,
  input      text        not null default '',
  expected   text        not null default '',
  hidden     boolean     not null default false,
  created_at timestamptz not null default now()
);

-- Execution history. No INSERT policy: only the server's service role writes
-- here, which is why the client treats a `run` broadcast as a "go re-read row
-- X" signal and never trusts the payload's results.
create table if not exists public.pl_runs (
  id              uuid primary key default gen_random_uuid(),
  session_id      uuid        not null references public.pl_sessions(id) on delete cascade,
  triggered_by    uuid        not null references auth.users(id) on delete cascade,
  language        text        not null,
  code            text        not null,
  status          text        not null default 'done' check (status in ('done','error')),
  summary         jsonb       not null default '{}',
  visible_results jsonb       not null default '[]',
  error           text,
  created_at      timestamptz not null default now()
);

-- Per-run hidden-case detail (may contain hidden inputs and stderr).
-- Interviewer-only by RLS and written only by the service role.
create table if not exists public.pl_run_hidden_results (
  run_id     uuid primary key references public.pl_runs(id) on delete cascade,
  session_id uuid  not null references public.pl_sessions(id) on delete cascade,
  details    jsonb not null default '[]'
);

-- Inline code review threads.
--
-- author_name/author_role are denormalised and client-written: the INSERT
-- policy pins author_id to auth.uid() but says nothing about the other two, so
-- a participant CAN lie in them. The UI therefore resolves display identity
-- from pl_session_participants by author_id and treats these columns only as a
-- fallback for authors who have left the room.
create table if not exists public.pl_comments (
  id          uuid primary key default gen_random_uuid(),
  session_id  uuid        not null references public.pl_sessions(id) on delete cascade,
  line_number integer     not null,
  author_id   uuid        not null references auth.users(id) on delete cascade,
  author_name text        not null default '',
  author_role text        not null default 'candidate' check (author_role in ('interviewer','candidate')),
  body        text        not null,
  created_at  timestamptz not null default now()
);

-- Interviewer line/range pins.
create table if not exists public.pl_highlights (
  id          uuid primary key default gen_random_uuid(),
  session_id  uuid        not null references public.pl_sessions(id) on delete cascade,
  line_number integer     not null,
  col_start   integer,
  col_end     integer,
  created_by  uuid        not null references auth.users(id) on delete cascade,
  created_at  timestamptz not null default now()
);

-- Audit trail for the hint ladder. 0002_hints_assign.sql revokes
-- pl_sessions.hints from clients and makes pl_reveal_hint() the only writer.
create table if not exists public.pl_hint_reveals (
  session_id  uuid        not null references public.pl_sessions(id) on delete cascade,
  hint_index  integer     not null,
  revealed_by uuid        not null references auth.users(id) on delete cascade,
  created_at  timestamptz not null default now(),
  primary key (session_id, hint_index)
);

-- Append-only whiteboard log (no DELETE policy). loadWhiteboard() replays
-- add/erase/clear in id order to rebuild the board.
create table if not exists public.pl_whiteboard_events (
  id         bigint generated always as identity primary key,
  session_id uuid        not null references public.pl_sessions(id) on delete cascade,
  author_id  uuid        not null references auth.users(id) on delete cascade,
  kind       text        not null check (kind in ('add','erase','clear')),
  payload    jsonb       not null default '{}',
  created_at timestamptz not null default now()
);

create table if not exists public.pl_interviewer_notes (
  session_id     uuid        not null references public.pl_sessions(id) on delete cascade,
  interviewer_id uuid        not null references auth.users(id) on delete cascade,
  body           text        not null default '',
  updated_at     timestamptz not null default now(),
  primary key (session_id, interviewer_id)
);

create table if not exists public.pl_candidate_notes (
  session_id uuid        not null references public.pl_sessions(id) on delete cascade,
  user_id    uuid        not null references auth.users(id) on delete cascade,
  body       text        not null default '',
  updated_at timestamptz not null default now(),
  primary key (session_id, user_id)
);

create table if not exists public.pl_rubric_scores (
  session_id     uuid        not null references public.pl_sessions(id) on delete cascade,
  interviewer_id uuid        not null references auth.users(id) on delete cascade,
  criterion      text        not null,
  score          integer     not null default 0 check (score >= 0 and score <= 4),
  updated_at     timestamptz not null default now(),
  primary key (session_id, interviewer_id, criterion)
);

-- ---------------------------------------------------------------------------
-- Indexes
-- ---------------------------------------------------------------------------
create index if not exists pl_sessions_created_by_idx on public.pl_sessions (created_by);
create index if not exists pl_sessions_room_key_idx   on public.pl_sessions (room_key);
create index if not exists pl_participants_session_idx on public.pl_session_participants (session_id);
create index if not exists pl_participants_user_idx    on public.pl_session_participants (user_id);
create index if not exists pl_test_cases_session_idx   on public.pl_test_cases (session_id);
create index if not exists pl_runs_session_idx         on public.pl_runs (session_id, created_at desc);
create index if not exists pl_comments_session_idx     on public.pl_comments (session_id);
create index if not exists pl_highlights_session_idx   on public.pl_highlights (session_id);
create index if not exists pl_wb_events_session_idx    on public.pl_whiteboard_events (session_id, id);

-- Enforces the single candidate seat at the storage layer, so the seat_taken
-- check inside pl_join_session cannot be raced by two simultaneous joins.
create unique index if not exists pl_one_candidate_per_session
  on public.pl_session_participants (session_id)
  where role = 'candidate';

-- ---------------------------------------------------------------------------
-- Helper functions (SECURITY DEFINER — they read pl_session_participants,
-- whose own SELECT policy would otherwise recurse)
-- ---------------------------------------------------------------------------
create or replace function public.pl_is_participant(p_session_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.pl_session_participants
    where session_id = p_session_id and user_id = auth.uid()
  );
$$;

create or replace function public.pl_is_interviewer(p_session_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.pl_session_participants
    where session_id = p_session_id and user_id = auth.uid() and role = 'interviewer'
  );
$$;

-- ---------------------------------------------------------------------------
-- Row-level security
-- ---------------------------------------------------------------------------
alter table public.pl_profiles             enable row level security;
alter table public.pl_problems             enable row level security;
alter table public.pl_sessions             enable row level security;
alter table public.pl_session_participants enable row level security;
alter table public.pl_session_invites      enable row level security;
alter table public.pl_test_cases           enable row level security;
alter table public.pl_runs                 enable row level security;
alter table public.pl_run_hidden_results   enable row level security;
alter table public.pl_comments             enable row level security;
alter table public.pl_highlights           enable row level security;
alter table public.pl_hint_reveals         enable row level security;
alter table public.pl_whiteboard_events    enable row level security;
alter table public.pl_interviewer_notes    enable row level security;
alter table public.pl_candidate_notes      enable row level security;
alter table public.pl_rubric_scores        enable row level security;

-- pl_profiles: own row only. No INSERT policy — rows come from the trigger.
drop policy if exists pl_profiles_select_own on public.pl_profiles;
create policy pl_profiles_select_own on public.pl_profiles
  for select to authenticated using (id = auth.uid());

drop policy if exists pl_profiles_update_own on public.pl_profiles;
create policy pl_profiles_update_own on public.pl_profiles
  for update to authenticated using (id = auth.uid()) with check (id = auth.uid());

-- pl_problems: builtins + own. Anonymous users see nothing, and cannot author
-- a problem (which would otherwise let them plant a fake "builtin").
drop policy if exists pl_problems_select on public.pl_problems;
create policy pl_problems_select on public.pl_problems
  for select to authenticated using (
    coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) = false
    and (owner_id is null or owner_id = auth.uid())
  );

drop policy if exists pl_problems_insert_own on public.pl_problems;
create policy pl_problems_insert_own on public.pl_problems
  for insert to authenticated with check (
    owner_id = auth.uid()
    and coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) = false
  );

drop policy if exists pl_problems_update_own on public.pl_problems;
create policy pl_problems_update_own on public.pl_problems
  for update to authenticated using (owner_id = auth.uid()) with check (owner_id = auth.uid());

drop policy if exists pl_problems_delete_own on public.pl_problems;
create policy pl_problems_delete_own on public.pl_problems
  for delete to authenticated using (owner_id = auth.uid());

-- pl_sessions: creator or seated participant. Anonymous users cannot create.
drop policy if exists pl_sessions_select on public.pl_sessions;
create policy pl_sessions_select on public.pl_sessions
  for select to authenticated using (created_by = auth.uid() or public.pl_is_participant(id));

drop policy if exists pl_sessions_insert on public.pl_sessions;
create policy pl_sessions_insert on public.pl_sessions
  for insert to authenticated with check (
    created_by = auth.uid()
    and coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) = false
  );

drop policy if exists pl_sessions_update_interviewer on public.pl_sessions;
create policy pl_sessions_update_interviewer on public.pl_sessions
  for update to authenticated
  using (public.pl_is_interviewer(id) or created_by = auth.uid())
  with check (public.pl_is_interviewer(id) or created_by = auth.uid());

drop policy if exists pl_sessions_delete_creator on public.pl_sessions;
create policy pl_sessions_delete_creator on public.pl_sessions
  for delete to authenticated using (created_by = auth.uid());

-- pl_session_participants: READ ONLY for clients. Seating happens exclusively
-- inside pl_join_session. Do not add a write policy here.
drop policy if exists pl_participants_select on public.pl_session_participants;
create policy pl_participants_select on public.pl_session_participants
  for select to authenticated using (public.pl_is_participant(session_id));

-- pl_session_invites: interviewers (or the creator, who has not been seated yet
-- at the moment /api/sessions writes the invites).
drop policy if exists pl_invites_select on public.pl_session_invites;
create policy pl_invites_select on public.pl_session_invites
  for select to authenticated using (public.pl_is_interviewer(session_id) or invited_by = auth.uid());

drop policy if exists pl_invites_insert on public.pl_session_invites;
create policy pl_invites_insert on public.pl_session_invites
  for insert to authenticated with check (
    invited_by = auth.uid()
    and (
      public.pl_is_interviewer(session_id)
      or exists (select 1 from public.pl_sessions s where s.id = session_id and s.created_by = auth.uid())
    )
  );

drop policy if exists pl_invites_delete on public.pl_session_invites;
create policy pl_invites_delete on public.pl_session_invites
  for delete to authenticated using (public.pl_is_interviewer(session_id) or invited_by = auth.uid());

-- pl_test_cases: two SELECT policies, deliberately split on `hidden`. This is
-- the mechanism that keeps hidden inputs away from the candidate; the /api/run
-- handler reads them with the service role instead.
drop policy if exists pl_test_cases_select_visible on public.pl_test_cases;
create policy pl_test_cases_select_visible on public.pl_test_cases
  for select to authenticated using (hidden = false and public.pl_is_participant(session_id));

drop policy if exists pl_test_cases_select_hidden on public.pl_test_cases;
create policy pl_test_cases_select_hidden on public.pl_test_cases
  for select to authenticated using (hidden = true and public.pl_is_interviewer(session_id));

drop policy if exists pl_test_cases_write on public.pl_test_cases;
create policy pl_test_cases_write on public.pl_test_cases
  for insert to authenticated with check (public.pl_is_interviewer(session_id));

drop policy if exists pl_test_cases_update on public.pl_test_cases;
create policy pl_test_cases_update on public.pl_test_cases
  for update to authenticated using (public.pl_is_interviewer(session_id));

drop policy if exists pl_test_cases_delete on public.pl_test_cases;
create policy pl_test_cases_delete on public.pl_test_cases
  for delete to authenticated using (public.pl_is_interviewer(session_id));

-- pl_runs / pl_run_hidden_results: read-only for clients (service role writes).
drop policy if exists pl_runs_select on public.pl_runs;
create policy pl_runs_select on public.pl_runs
  for select to authenticated using (public.pl_is_participant(session_id));

drop policy if exists pl_run_hidden_select on public.pl_run_hidden_results;
create policy pl_run_hidden_select on public.pl_run_hidden_results
  for select to authenticated using (public.pl_is_interviewer(session_id));

-- pl_comments: any participant may comment as themselves and delete their own.
drop policy if exists pl_comments_select on public.pl_comments;
create policy pl_comments_select on public.pl_comments
  for select to authenticated using (public.pl_is_participant(session_id));

drop policy if exists pl_comments_insert on public.pl_comments;
create policy pl_comments_insert on public.pl_comments
  for insert to authenticated with check (author_id = auth.uid() and public.pl_is_participant(session_id));

drop policy if exists pl_comments_delete_own on public.pl_comments;
create policy pl_comments_delete_own on public.pl_comments
  for delete to authenticated using (author_id = auth.uid());

-- pl_highlights: everyone sees the pins, only interviewers place them.
drop policy if exists pl_highlights_select on public.pl_highlights;
create policy pl_highlights_select on public.pl_highlights
  for select to authenticated using (public.pl_is_participant(session_id));

drop policy if exists pl_highlights_insert on public.pl_highlights;
create policy pl_highlights_insert on public.pl_highlights
  for insert to authenticated with check (created_by = auth.uid() and public.pl_is_interviewer(session_id));

drop policy if exists pl_highlights_delete on public.pl_highlights;
create policy pl_highlights_delete on public.pl_highlights
  for delete to authenticated using (public.pl_is_interviewer(session_id));

-- pl_hint_reveals: append-only audit row, attributable to its author.
drop policy if exists pl_hints_select on public.pl_hint_reveals;
create policy pl_hints_select on public.pl_hint_reveals
  for select to authenticated using (public.pl_is_participant(session_id));

drop policy if exists pl_hints_insert on public.pl_hint_reveals;
create policy pl_hints_insert on public.pl_hint_reveals
  for insert to authenticated with check (revealed_by = auth.uid() and public.pl_is_participant(session_id));

-- pl_whiteboard_events: append-only, author pinned to the caller.
drop policy if exists pl_wb_select on public.pl_whiteboard_events;
create policy pl_wb_select on public.pl_whiteboard_events
  for select to authenticated using (public.pl_is_participant(session_id));

drop policy if exists pl_wb_insert on public.pl_whiteboard_events;
create policy pl_wb_insert on public.pl_whiteboard_events
  for insert to authenticated with check (author_id = auth.uid() and public.pl_is_participant(session_id));

-- pl_interviewer_notes / pl_rubric_scores: interviewer-only, INCLUDING SELECT.
-- The candidate must never be able to read either.
drop policy if exists pl_int_notes_select on public.pl_interviewer_notes;
create policy pl_int_notes_select on public.pl_interviewer_notes
  for select to authenticated using (public.pl_is_interviewer(session_id));

drop policy if exists pl_int_notes_insert on public.pl_interviewer_notes;
create policy pl_int_notes_insert on public.pl_interviewer_notes
  for insert to authenticated with check (interviewer_id = auth.uid() and public.pl_is_interviewer(session_id));

drop policy if exists pl_int_notes_update on public.pl_interviewer_notes;
create policy pl_int_notes_update on public.pl_interviewer_notes
  for update to authenticated using (interviewer_id = auth.uid() and public.pl_is_interviewer(session_id));

drop policy if exists pl_rubric_select on public.pl_rubric_scores;
create policy pl_rubric_select on public.pl_rubric_scores
  for select to authenticated using (public.pl_is_interviewer(session_id));

drop policy if exists pl_rubric_upsert on public.pl_rubric_scores;
create policy pl_rubric_upsert on public.pl_rubric_scores
  for insert to authenticated with check (interviewer_id = auth.uid() and public.pl_is_interviewer(session_id));

drop policy if exists pl_rubric_update on public.pl_rubric_scores;
create policy pl_rubric_update on public.pl_rubric_scores
  for update to authenticated using (interviewer_id = auth.uid() and public.pl_is_interviewer(session_id));

-- pl_candidate_notes: private scratchpad, own row only.
drop policy if exists pl_cand_notes_all on public.pl_candidate_notes;
create policy pl_cand_notes_all on public.pl_candidate_notes
  for all to authenticated
  using (user_id = auth.uid() and public.pl_is_participant(session_id))
  with check (user_id = auth.uid() and public.pl_is_participant(session_id));

-- ---------------------------------------------------------------------------
-- Column-level grants
-- ---------------------------------------------------------------------------
-- RLS filters rows, never columns. pl_problems.hidden_tests is the one secret
-- that lives in a row a user is otherwise allowed to read (every builtin), so
-- the protection has to be a column grant. Revoke SELECT on the whole table and
-- re-grant it column by column, omitting hidden_tests.
--
-- If you add a column to pl_problems, add it here too or it will be invisible
-- to the client.
revoke select on public.pl_problems from authenticated;
grant select (
  id, owner_id, number, title, difficulty, description, follow_up,
  tags, hints, starter_code, visible_tests, created_at
) on public.pl_problems to authenticated;

-- `anon` gets nothing anywhere: every policy above is scoped `to authenticated`
-- and Supabase's default grants leave anon without SELECT on these tables.

-- ---------------------------------------------------------------------------
-- Application functions
-- ---------------------------------------------------------------------------

-- The only way to become a participant.
--
-- Role derivation, in order:
--   1. creator of the session          -> interviewer
--   2. confirmed email on the invite   -> interviewer
--   3. anyone else                     -> candidate (single seat)
-- A rejoin returns the previously assigned role and never re-derives it, so
-- revoking an invite cannot silently demote someone mid-interview, and a
-- candidate cannot be promoted by adding their address after they joined.
create or replace function public.pl_join_session(p_key text, p_display_name text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_email text := lower(coalesce(auth.jwt() ->> 'email', ''));
  v_is_anon boolean := coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false);
  v_email_confirmed boolean;
  v_session public.pl_sessions%rowtype;
  v_existing public.pl_session_participants%rowtype;
  v_role text;
  v_name text;
  v_color text;
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  select * into v_session
  from public.pl_sessions
  where upper(room_key) = upper(trim(p_key));

  if not found then
    raise exception 'invalid_key';
  end if;

  if v_session.status = 'completed' then
    raise exception 'session_completed';
  end if;

  -- rejoin: keep the previously assigned role, never re-derive it
  select * into v_existing
  from public.pl_session_participants
  where session_id = v_session.id and user_id = v_uid;

  if found then
    return jsonb_build_object('session_id', v_session.id, 'role', v_existing.role);
  end if;

  select (email_confirmed_at is not null) into v_email_confirmed
  from auth.users where id = v_uid;

  if v_uid = v_session.created_by then
    v_role := 'interviewer';
  elsif (not v_is_anon) and coalesce(v_email_confirmed, false) and v_email <> '' and exists (
    select 1 from public.pl_session_invites
    where session_id = v_session.id and lower(email) = v_email
  ) then
    v_role := 'interviewer';
  else
    v_role := 'candidate';
    if exists (
      select 1 from public.pl_session_participants
      where session_id = v_session.id and role = 'candidate' and user_id <> v_uid
    ) then
      raise exception 'seat_taken';
    end if;
  end if;

  if v_role = 'candidate' then
    v_name := coalesce(nullif(trim(p_display_name), ''), v_session.candidate_name);
    v_color := '#5b8cff';
  else
    select coalesce(nullif(trim(p_display_name), ''), display_name, 'Interviewer')
      into v_name from public.pl_profiles where id = v_uid;
    v_name := coalesce(v_name, 'Interviewer');
    v_color := '#3ddc97';
  end if;

  insert into public.pl_session_participants (session_id, user_id, role, display_name, color)
  values (v_session.id, v_uid, v_role, v_name, v_color)
  on conflict (session_id, user_id) do nothing;

  return jsonb_build_object('session_id', v_session.id, 'role', v_role);
end;
$$;

-- Persist the shared editor buffer. SECURITY DEFINER so a participant can write
-- one jsonb key of pl_sessions.code without holding UPDATE on the whole row
-- (which pl_sessions_update_interviewer reserves for interviewers).
create or replace function public.pl_save_code(p_session_id uuid, p_language text, p_code text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.pl_is_participant(p_session_id) then
    raise exception 'not_a_participant';
  end if;
  if p_language not in ('python', 'javascript', 'java', 'cpp', 'go') then
    raise exception 'bad_language';
  end if;
  update public.pl_sessions
  set language = p_language,
      code = jsonb_set(coalesce(code, '{}'::jsonb), array[p_language], to_jsonb(p_code))
  where id = p_session_id and status <> 'completed';
end;
$$;

-- Lets the candidate see HOW MANY hidden cases exist without seeing any of
-- them — pl_test_cases_select_hidden would return zero rows for them.
create or replace function public.pl_hidden_test_count(p_session_id uuid)
returns integer language plpgsql stable security definer set search_path = public as $$
declare
  v_count int;
begin
  if not public.pl_is_participant(p_session_id) then
    raise exception 'not_a_participant';
  end if;
  select count(*) into v_count
  from public.pl_test_cases
  where session_id = p_session_id and hidden = true;
  return v_count;
end;
$$;

-- ---------------------------------------------------------------------------
-- Auth trigger
-- ---------------------------------------------------------------------------
create or replace function public.pl_handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.pl_profiles (id, display_name, email, is_anonymous)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'display_name', split_part(coalesce(new.email, ''), '@', 1)),
    new.email,
    coalesce(new.is_anonymous, false)
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists pl_on_auth_user_created on auth.users;
create trigger pl_on_auth_user_created
  after insert on auth.users
  for each row execute function public.pl_handle_new_user();

-- ---------------------------------------------------------------------------
-- Realtime
-- ---------------------------------------------------------------------------
-- No pl_ table is added to the supabase_realtime publication, and that is
-- deliberate: postgres_changes would stream whole rows to every subscriber,
-- bypassing the column-level protections above. The app uses private broadcast
-- channels (topic `pl:session:<id>`) instead, and every broadcast is treated as
-- a "go re-read row X" signal rather than as data — see useStudio.ts.
-- Private channels require Realtime authorization to be enabled in the
-- dashboard (Project Settings -> Realtime).
--
-- Only participants of a session may subscribe to or broadcast on its topic.
drop policy if exists pl_realtime_select on realtime.messages;
create policy pl_realtime_select on realtime.messages
  for select to authenticated
  using (
    realtime.topic() like 'pl:session:%'
    and public.pl_is_participant((split_part(realtime.topic(), ':', 3))::uuid)
  );

drop policy if exists pl_realtime_insert on realtime.messages;
create policy pl_realtime_insert on realtime.messages
  for insert to authenticated
  with check (
    realtime.topic() like 'pl:session:%'
    and public.pl_is_participant((split_part(realtime.topic(), ':', 3))::uuid)
  );
